<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>Morning Walk — Alpaca</title>
<style>
  html, body { margin:0; padding:0; height:100%; overflow:hidden; background:#7fb0cc; }
  #stage { display:block; width:100vw; height:100vh; }
  .caption {
    position:fixed; left:36px; bottom:26px; pointer-events:none; user-select:none;
    font-family:Georgia,'Times New Roman',serif; font-size:13px; letter-spacing:.24em;
    text-transform:uppercase; color:rgba(74,58,38,.55);
